package com.smartsocietyconnect.announcement;
import java.time.*; import jakarta.persistence.*; import lombok.*; import com.smartsocietyconnect.auth.entity.User;
@Entity @Table(name="announcements") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Announcement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer id; @Column(nullable=false,length=150) private String title; @Column(nullable=false,columnDefinition="TEXT") private String message; @Column(nullable=false,length=30) private String category; @Column(nullable=false,length=20) private String priority; @Column(nullable=false,length=30) private String audience; @Column(nullable=false) private LocalDateTime publishAt; private LocalDateTime expiresAt; @Column(nullable=false) @Builder.Default private Boolean published=true; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by",nullable=false) private User createdBy; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); }
